-- Referral tiers, wording (Sean, 2026-11-03: a sponsor gets the 111 points when the friend completes the survey).
-- Behavior is unchanged (ve_referral_on_admit: Level 1 points; Level 2 commission only when the friend paid, points on a survey join; Level 3+ both).
update knowledge_records set body = replace(body::text, 'A friend who joins with it and becomes a member earns them 111 points, and from Level 2 the link earns a commission:', 'A friend who joins with it and becomes a member earns them 111 points (at Level 2 a friend who pays earns the commission instead, while a friend who joins free by finishing the survey still earns the 111 points; from Level 3 both), and from Level 2 the link earns a commission:')::jsonb, version = version + 1
 where slug = 've-guide-platform-facts' and body::text like '%A friend who joins with it and becomes a member earns them 111 points, and from Level 2%';
update guide_kb_answers set answer = replace(answer, 'a friend who becomes a member earns you 111 points, and from Level 2 you also earn', 'a friend who becomes a member earns you 111 points (at Level 2 a friend who pays earns the commission instead, a friend who joins free by finishing the survey still earns the 111 points, and from Level 3 you get both), and from Level 2 you also earn') where id = '8dc33c97-9be8-4cbf-8b0b-4b83bcc5f55f';
update guide_kb_answers set answer = 'You get 111 points when a friend you refer joins, whether they pay the $11 or finish the survey. From Level 2, a friend who pays earns you the commission instead of the points; from Level 3 you get both. They can enter your referral code when they sign up.' where id = '301cad56-a07e-4373-854f-eec06a1083b7';
